using System;using System.IO;using System.Security.Cryptography;
namespace CodexLight.Bootstrap {
 internal static class BoundedFile {
  public static byte[] Read(string path,int maxBytes){if(maxBytes<0)throw new ArgumentOutOfRangeException(nameof(maxBytes));if(new FileInfo(path).Length>maxBytes)throw new InvalidOperationException("Metadata exceeds size limit");using(var stream=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read)){if(stream.Length>maxBytes)throw new InvalidOperationException("Metadata exceeds size limit");return Read(stream,maxBytes);}}
  // Stream overload also bounds streams whose Length is stale/unavailable or grow after checking.
  public static byte[] Read(Stream stream,int maxBytes){if(maxBytes<0)throw new ArgumentOutOfRangeException(nameof(maxBytes));using(var output=new MemoryStream()){var buffer=new byte[8192];int count,total=0;while((count=stream.Read(buffer,0,(int)Math.Min(buffer.Length,(long)maxBytes-total+1)))>0){if((long)total+count>maxBytes)throw new InvalidOperationException("Metadata grew beyond size limit");output.Write(buffer,0,count);total+=count;}return output.ToArray();}}
  public static void Copy(string source,string destination,long expectedSize){if(expectedSize<0||expectedSize>1024L*1024*1024||new FileInfo(source).Length!=expectedSize)throw new InvalidOperationException("Source size changed");using(var input=new FileStream(source,FileMode.Open,FileAccess.Read,FileShare.Read))using(var output=new FileStream(destination,FileMode.CreateNew,FileAccess.Write,FileShare.None)){if(input.Length!=expectedSize)throw new InvalidOperationException("Source size changed");var buffer=new byte[65536];long total=0;int count;while((count=input.Read(buffer,0,(int)Math.Min(buffer.Length,expectedSize-total+1)))>0){if(total+count>expectedSize)throw new InvalidOperationException("Source grew during copy");output.Write(buffer,0,count);total+=count;}if(total!=expectedSize)throw new InvalidOperationException("Source shrank during copy");output.Flush(true);}}
  public static void CopyMetadata(string source,string destination,int maxBytes){var bytes=Read(source,maxBytes);using(var output=new FileStream(destination,FileMode.CreateNew,FileAccess.Write,FileShare.None)){output.Write(bytes,0,bytes.Length);output.Flush(true);}}
  public static string Hash(string path,long expectedSize){if(expectedSize<0||expectedSize>1024L*1024*1024)throw new InvalidOperationException("File size outside supported bound");if(new FileInfo(path).Length!=expectedSize)throw new InvalidOperationException("File size changed");using(var stream=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read)){if(stream.Length!=expectedSize)throw new InvalidOperationException("File size changed");return Hash(stream,expectedSize);}}
  public static string Hash(Stream stream,long expectedSize){if(expectedSize<0||expectedSize>1024L*1024*1024)throw new InvalidOperationException("File size outside supported bound");using(var hash=SHA256.Create()){var buffer=new byte[65536];long total=0;int count;while((count=stream.Read(buffer,0,(int)Math.Min(buffer.Length,expectedSize-total+1)))>0){if(total+count>expectedSize)throw new InvalidOperationException("File grew during hashing");hash.TransformBlock(buffer,0,count,buffer,0);total+=count;}if(total!=expectedSize)throw new InvalidOperationException("File shrank during hashing");hash.TransformFinalBlock(Array.Empty<byte>(),0,0);return BitConverter.ToString(hash.Hash!).Replace("-","").ToLowerInvariant();}}
 }
}
